            ->add('custom_value', TranslatableType::class, [
                'label' => false,
                'required' => false,
                'type' => TextType::class,
                'row_attr' => [
                    'class' => 'custom-values-form-group',
                ],
                'constraints' => [
                    new DefaultLanguage([
                        'message' => $this->trans(
                            'The field %field_name% is required at least in your default language.',
                            'Admin.Notifications.Error',
